#pragma once
// Palette entries for the generic game-UI nodes. NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after
// pin()/attr() are defined, and calls appendUiExtNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphUiExtNodeTable.cs pin for pin
// (docs/plans/wave9/VISUAL_SCRIPTING_CSHARP_SYNC.md section 2.2). Widgets are ints, like the existing AN_*Ui* nodes. Property
// names, list items (separated by a bar) and the theme are attributes. UI scale is not here: the accessibility option
// graphics.uiScale owns it.

inline void appendUiExtNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_SetUiProperty", "Set UI Property", "UI", {
        pin("exec", "exec", false), pin("widget", "int", false), pin("value", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)},
        {attr("property", "Property name")}});
    t.push_back({"AN_SetUiPropertyText", "Set UI Property Text", "UI", {
        pin("exec", "exec", false), pin("widget", "int", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("property", "Property name"), attr("text", "Value (empty clears)")}});
    t.push_back({"AN_SetUiItems", "Set UI Items", "UI", {
        pin("exec", "exec", false), pin("widget", "int", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("items", "Items, separated by bars (empty clears)")}});
    t.push_back({"AN_SetUiSelected", "Set UI Selected", "UI", {
        pin("exec", "exec", false), pin("widget", "int", false), pin("index", "int", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_SetUiTheme", "Set UI Theme", "UI", {
        pin("exec", "exec", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("theme", "Theme name")}});
    t.push_back({"AN_GetUiInputState", "Get UI Input State", "UI", {
        pin("pointer", "bool", true), pin("keyboard", "bool", true), pin("pausesGame", "bool", true), pin("showCursor", "bool", true)}});
}
